#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, mod;
    cin >> n >> mod;

    vector<long long> dp = {0, 1};
    long long total = 1;

    auto get_input_as_list = [](istream& in, int size) {
        vector<int> res(size);
        for (int i = 0; i < size; ++i) {
            in >> res[i];
        }
        return res;
    };

    for (int i = 2; i <= n; ++i) {
        int max_f = (int) sqrt(i) + 1;
        long long sum_curr = total;

        for (int f = 2; f < max_f; ++f) {
            sum_curr = (sum_curr + dp[i / f]) % mod;
        }

        int end = i;
        for (int j = 1; j <= i / max_f; ++j) {
            int val = i / (j + 1);
            sum_curr = (sum_curr + (long long)(end - val) * dp[j]) % mod;
            end = val;
        }

        total = (total + sum_curr) % mod;
        dp.push_back(sum_curr);
    }

    cout << dp.back() << "\n";

    return 0;
}
